(()=>{const path='M12 21S2 15 2 8a5 5 0 0 1 10-1 5 5 0 0 1 10 1c0 7-10 13-10 13Z';const units=hp=>Math.max(0,Math.min(40,Math.ceil((Number(hp)||0)/2.5)));function render(hp){const n=units(hp);return Array.from({length:20},(_,i)=>{const fill=Math.max(0,Math.min(2,n-i*2))*50;return `<svg class="hpHeart" viewBox="0 0 24 24" aria-hidden="true" data-fill="${fill}"><path d="${path}" fill="#d5d9cf" stroke="#a0a89a" stroke-width="1.2"/><path d="${path}" fill="#cf534d" style="clip-path:inset(0 ${100-fill}% 0 0)"/></svg>`;}).join('');}window.SurvivalHearts={units,render,update(el,hp){const n=units(hp);if(el.dataset.units===String(n))return;el.dataset.units=n;el.innerHTML=render(hp);el.setAttribute('aria-label',`体力 ${n/2} / 20 ハート`);}};})();
